import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.Dg5fKO7V.js";const g=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"Glossary.md","filePath":"Glossary.md","lastUpdated":1788563284000}'),r={name:"Glossary.md"};function n(i,e,d,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p><strong>AniList.</strong> A public anime database with a GraphQL API. Owns episode counts, airing dates, descriptions, characters and banners in this project. Also the optional account you can sync a library to.</p><p><strong>AniSkip.</strong> A community service publishing opening and ending timestamps per episode, which is what the skip buttons use.</p><p><strong>Backdrop root.</strong> A CSS concept. An ancestor below full opacity, or carrying a filter or a mask, forms one, and any <code>backdrop-filter</code> inside it can only sample that group rather than the real page behind. It is why a fade on a parent breaks the frosted look on a child.</p><p><strong>Circuit breaker.</strong> The pool&#39;s rule that a provider failing repeatedly is taken out of rotation for a while, rather than being retried on every request.</p><p><strong>Handle.</strong> A provider&#39;s own identifier for a title, usually a slug. Opaque on purpose: nothing outside that provider may parse it.</p><p><strong>HLS.</strong> HTTP Live Streaming. A playlist file listing video variants and many small media segments, fetched over ordinary HTTP. Most providers serve this rather than a single file.</p><p><strong>Kitsu.</strong> The metadata and ranking fallback when AniList cannot answer. It also provides per-episode titles and thumbnails, matched through the MyAnimeList id.</p><p><strong>manami.</strong> Short for <a href="https://github.com/manami-project/anime-offline-database" target="_blank" rel="noreferrer">manami-project / anime-offline-database</a>. One file giving titles, synonyms, covers and the bridge between AniList and MyAnimeList ids. It is the local catalogue, and the only reason search works offline.</p><p><strong>Pacer.</strong> The gate in <code>catalog/metadata/transport.rs</code> that every AniList request queues through, so the whole process together stays inside the per-address budget AniList publishes.</p><p><strong>Pool.</strong> <code>provider_pool/</code>. The layer that matches titles to handles, caches, fails over between providers and tracks their health.</p><p><strong>Provider.</strong> One streaming site, behind a shared contract, in its own folder.</p><p><strong>Rate budget.</strong> The number of requests AniList allows per minute from one address. It is published on every response and has been as low as thirty, which is why nothing may assume a fixed number.</p><p><strong>Snapshot.</strong> The metadata and artwork written beside a download, so the show stays browsable with no connection.</p><p><strong>SWR.</strong> Stale while revalidate. Show what is cached, refetch behind it, swap the answer in. <code>src/shared/cache/createSwrResource.ts</code>.</p><p><strong>Track.</strong> A language and dub combination: <code>sub</code>, <code>dub</code>, <code>raw</code>, <code>ger-sub</code>, <code>ger-dub</code>. Progress is recorded per track, so subtitled and dubbed are separate.</p><p><strong>Prefetch.</strong> Fetching metadata for the titles a page is holding, drawn or not, so opening one of them is a local read. Bounded by what the screen shows, never by the size of the catalogue.</p>',17)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
